mapper.select:
    select a.* from black_gray_warehouse_rule_config a
    
      
        and a.rule_name like concat('%',#{param.ruleName},'%')
      
      
        and a.black_gray_type = #{param.blackGrayType}
      
      
        and a.status = #{param.status}
      
      
        and a.source = #{param.source}
      
      
        and json_contains(a.suit_org -> '$',json_array(#{param.suitOrg}), '$')
      
      
        and json_contains(a.suit_business -> '$',json_array(#{param.suitBusiness}), '$')
      

    
    order by a.update_time desc
